<template><section class="module-page module-composed-page"><header class="module-heading action-heading"><div><h1>处理服务器</h1><p>下载一键部署包并查看已接入服务器。</p></div><el-button type="primary" icon="el-icon-plus" @click="tokenDialog=true">添加服务器</el-button></header><AgentStatusTable :agents="agents" :loading="loading" @select="selectAgent" /><div v-if="selected" class="operations-bar"><strong>{{ selected.displayName || selected.hostname }}</strong><span class="grow" /><el-button icon="el-icon-sunny" :loading="busyAction==='wake'" @click="wakeAgent">开机</el-button><el-button icon="el-icon-switch-button" :loading="busyAction==='shutdown'" :disabled="!selected.online" @click="shutdownAgent">关机</el-button><el-button v-if="selected.enabled" icon="el-icon-video-pause" @click="disableAgentAction">停用</el-button><el-button v-else type="success" icon="el-icon-video-play" @click="enableAgent">启用</el-button><el-button type="danger" plain icon="el-icon-delete" @click="removeAgent">移除</el-button></div><section v-if="selected" class="command-history"><h2>电源操作记录</h2><div class="module-table-wrap"><el-table :data="commands" empty-text="暂无操作记录" size="small"><el-table-column prop="requestedAt" label="发起时间" min-width="170" /><el-table-column label="状态" width="150"><template slot-scope="s"><el-tag size="small" :type="commandTag(s.row.state)">{{ commandState(s.row) }}</el-tag></template></el-table-column><el-table-column prop="resultMessage" label="结果" min-width="240" /></el-table></div></section><el-dialog title="添加服务器" :visible.sync="tokenDialog" width="520px" @closed="clearForm"><el-form v-if="!downloading" :model="form" label-width="100px"><el-form-item label="服务器 IP"><el-input v-model.trim="form.serverIp" placeholder="例如 172.16.33.215" /></el-form-item><el-form-item label="备注名称"><el-input v-model.trim="form.label" placeholder="例如：GPU 训练服务器" maxlength="80" /></el-form-item><el-form-item label="工作目录"><el-input v-model.trim="form.workspace" placeholder="/srv/xkp" /></el-form-item></el-form><div v-else class="adding-state"><i class="el-icon-loading" /><strong>正在生成部署包...</strong><span>{{ form.serverIp }}</span></div><span slot="footer"><el-button :disabled="downloading" @click="tokenDialog=false">关闭</el-button><el-button v-if="!downloading" type="primary" :loading="downloading" @click="downloadPackage">下载部署包</el-button></span></el-dialog><RootTerminalDialog v-if="terminalVisible" :visible.sync="terminalVisible" :session="terminalSession" :agent-name="selected && (selected.displayName || selected.hostname)" @closed="terminalSession=null" /></section></template>
<script>
import AgentStatusTable from '@/components/agents/AgentStatusTable.vue'
import RootTerminalDialog from '@/components/agents/RootTerminalDialog.vue'
import { listProcessingAgents, downloadAgentPackage, enableProcessingAgent, disableProcessingAgent, removeProcessingAgent, listProcessingAgentCommands, wakeProcessingAgent, shutdownProcessingAgent } from '@/api/ProcessingAgents'
import { createTerminalSession } from '@/api/TerminalSessions'
export default {components:{AgentStatusTable,RootTerminalDialog},data:()=>({agents:[],selected:null,commands:[],loading:false,busyAction:'',tokenDialog:false,downloading:false,form:{serverIp:'',label:'',workspace:'/srv/xkp'},terminalVisible:false,terminalSession:null}),mounted(){this.load()},methods:{async load(){this.loading=true;try{const r=await listProcessingAgents();this.agents=r.data||[]}finally{this.loading=false}},async selectAgent(agent){this.selected=agent;const r=await listProcessingAgentCommands(agent.agentId);this.commands=r.data||[]},async wakeAgent(){this.busyAction='wake';try{await wakeProcessingAgent(this.selected.agentId);this.$message.success('唤醒请求已提交')}finally{this.busyAction=''}},async shutdownAgent(){await this.$confirm('确认关闭服务器？','提示',{type:'warning'});this.busyAction='shutdown';try{await shutdownProcessingAgent(this.selected.agentId);await this.selectAgent(this.selected)}finally{this.busyAction=''}},async downloadPackage(){if(!this.form.serverIp||!this.form.label){this.$message.warning('请输入服务器 IP 和备注名称');return}this.downloading=true;try{const response=await downloadAgentPackage(this.form);const blob=response.data||response;const url=URL.createObjectURL(blob);const anchor=document.createElement('a');anchor.href=url;anchor.download=`${this.form.label}-xkp-agent.zip`;anchor.click();URL.revokeObjectURL(url);this.$message.success('Agent 部署包已下载');this.tokenDialog=false}finally{this.downloading=false}},clearForm(){this.form={serverIp:'',label:'',workspace:'/srv/xkp'}},async disableAgentAction(){await this.$confirm('停用该处理服务器？','提示',{type:'warning'});await disableProcessingAgent(this.selected.agentId);await this.load()},async enableAgent(){await enableProcessingAgent(this.selected.agentId);await this.load()},async removeAgent(){await this.$confirm('移除后需重新注册，确认继续？','提示',{type:'warning'});await removeProcessingAgent(this.selected.agentId);this.selected=null;await this.load()},commandState(c){return({PENDING:'等待 Agent 接收',LEASED:'已送达',RUNNING:'执行中',SUCCEEDED:'已完成',FAILED:c.resultMessage||'执行失败'})[c.state]||c.state},commandTag(s){return({PENDING:'info',LEASED:'',RUNNING:'warning',SUCCEEDED:'success',FAILED:'danger'})[s]||'info'}}}
</script>
<style scoped>.action-heading,.operations-bar{display:flex;align-items:center;justify-content:space-between}.operations-bar{min-height:58px;padding:0 16px;border:1px solid var(--ui-border);border-top:0}.grow{flex:1}.command-history{margin-top:24px}.command-history h2{margin:0 0 12px;font-size:16px}.adding-state{display:flex;flex-direction:column;align-items:center;gap:12px;padding:34px 0;color:var(--ui-muted)}.adding-state i{color:var(--ui-primary);font-size:30px}.adding-state strong{color:var(--ui-text);font-size:17px}
</style>
